// Generated by `pnpm nx g @app/generators:action overview.get`. Requests go through the real router
// with createTestEngine().inject. They fail until createOverviewGetAction is implemented; do not weaken them.
import { overviewGet } from '@app/contracts';
import { createRoleAuthorizer } from '@app/kernel';
import {
  createOverviewGetAction,
  createExplorerFakeDeps,
} from '@app/svc-explorer';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

// The test engine's caller is the launch-token user, who must own the fake connection.
const subject = () =>
  createOverviewGetAction(createExplorerFakeDeps({ ownerId: 'local-token' }));
const def = overviewGet;
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('GET /connections/{cid}/overview', () => {
  it('AC-1 the route runs overview.get and answers in the shape of the contract', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/overview',
    });

    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
  });

  it('AC-2 a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/overview',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('AC-3 a caller that does not hold broker.read gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/overview',
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('AC-4 input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/overview?unexpected=1',
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('AC-5 another method on the same path is 405', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'DELETE',
      path: '/connections/c1/overview',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('GET');
  });
});
